import{suspects,evidence,payments,deductions,canSearch,canAccuse,correctAccusation}from'./blackthorn-data.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({found:[],rows:[],deductions:[],timeline:{},solved:false,intro:false,hint:0,notes:''});let state=initial(),bookOpen=false,page=1,lastFocus=null;try{const saved=JSON.parse(localStorage.getItem('archive-case2'));if(saved?.found&&saved?.deductions)state={...initial(),...saved}}catch{}
function save(){try{localStorage.setItem('archive-case2',JSON.stringify(state))}catch{}status()}
function status(){let first;try{first=JSON.parse(localStorage.getItem('archive-case1'))}catch{}$('#case1status').textContent=first?.phase==='preserved'?'WITNESS RECORD PRESERVED':first?.clues?`${Object.keys(first.clues).length} / 3 memories recovered`:'A testimony waiting to be found.';$('#case2status').textContent=state.solved?'SOLVED / Revisit the completed dossier':`${state.found.length} records examined · ${state.deductions.length} / 3 deductions`;$('.page-two').classList.toggle('solved',state.solved)}
function openBook(){bookOpen=true;$('#book').classList.add('open');$('#openbook').setAttribute('aria-expanded','true');$('#openbook').inert=true;$('.spread').inert=false;$('.case-link').focus()}
$('#openbook').onclick=openBook;$('#closebook').onclick=()=>{bookOpen=false;$('#book').classList.remove('open');$('#openbook').inert=false;$('#openbook').setAttribute('aria-expanded','false');$('.spread').inert=true;$('#openbook').focus()};$('.spread').inert=true;
function setPage(n){page=n;$('#book').classList.toggle('page2',n===2);$('#pageindicator').textContent=`Page ${n} of 2`;$('#prevpage').disabled=n===1;$('#nextpage').disabled=n===2;if(!bookOpen)openBook()}
$('#prevpage').onclick=()=>setPage(1);$('#nextpage').onclick=()=>setPage(2);setPage(1);$('#book').classList.remove('open');bookOpen=false;$('#openbook').inert=false;$('#openbook').setAttribute('aria-expanded','false');$('.spread').inert=true;
function route(){const path=location.hash||'#/';$('#evidence-dialog').close();$('#hub').hidden=path!=='#/';$('#caseframe').hidden=path!=='#/case/desktop';$('#blackthorn').hidden=path!=='#/case/blackthorn';if(path==='#/case/desktop'){if(!$('#caseframe').getAttribute('src'))$('#caseframe').src='desktop.html'}else if(path==='#/case/blackthorn'){renderDesk();if(!state.intro)openPaper('intro')}else{if(path!=='#/')location.hash='#/';status();if(bookOpen)openBook()}document.title=path==='#/case/blackthorn'?'Blackthorn Manor — The Archive':path==='#/case/desktop'?'Desktop of a Stranger — The Archive':'The Archive of the Unexplained'}
addEventListener('hashchange',route);addEventListener('storage',status);
const objects=[['dossier','▤','The case dossier','ASSIGNMENT / 14 NOVEMBER'],['suspects','♟','Four persons of interest','PORTRAITS & STATEMENTS'],['clock','◷','The bronze clock','EXHIBIT A / STOPPED HANDS'],['gardener','✒','A reluctant witness','EXHIBIT B / CONSERVATORY'],['key','⚿','The key register','EXHIBIT C / ESTATE OFFICE'],['bell','♧','The study bell-pull','EXHIBIT D / SCORCHED THREAD'],['finance','£','Accounts & receipts','EXHIBIT E / THREE FAMILIES'],['search','▣','Clara’s writing case','EXHIBIT F / SEARCH REQUIRED'],['medical','✚','Examiner’s notes','OBSERVATIONS / 10:24 PM'],['floor','⌑','The ground floor','SURVEY / NO SECRET PASSAGE'],['board','⌘','The evidence board','CONNECT / DEDUCE'],['accuse','✦','The sealed accusation','YOUR CONCLUSION']];
function renderDesk(){const shown=$('#showobjects')?.checked;$('#blackthorn').innerHTML=`<nav class="case-nav"><a href="#/">← Return to the archive</a><span>BLACKTHORN MANOR / CASE 002</span><button data-paper="restart">Restart this case</button></nav><header class="case-intro"><span class="eyebrow">NOVEMBER 1900 · LATE VICTORIAN ENGLAND</span><h1>The Last Bell at<br><em>Blackthorn Manor</em></h1><p>Determine who killed Sir Edmund, how the locked room was staged,<br>and which evidence proves it.</p></header><div class="desk-tools"><button data-paper="notebook">▤ Investigator’s notebook</button><button data-paper="timeline">◷ Arrange the timeline</button>${state.solved?'<button data-paper="report">✦ Read final case report</button>':''}<label><input id="showobjects" type="checkbox" ${shown?'checked':''}> Show inspectable objects</label><span class="eyebrow">${state.deductions.length} / 3 DEDUCTIONS</span></div><main class="evidence-desk ${shown?'inspectable':''}">${objects.map(([id,symbol,title,sub])=>`<button class="object ${state.found.includes(id)?'inspected':''} ${id==='accuse'?'seal-object':''}" data-paper="${id}"><span class="obj-symbol" aria-hidden="true">${symbol}</span><span class="obj-title">${title}</span><small>${sub}</small></button>`).join('')}</main><footer class="desk-bottom">FICTIONAL INVESTIGATION · NO LIVE SERVICES · PROGRESS SAVED ONLY IN THIS BROWSER</footer>`;$('#showobjects').onchange=e=>$('.evidence-desk').classList.toggle('inspectable',e.target.checked)}
const paper=(title,body,label='BLACKTHORN ARCHIVE / PRIVATE DOSSIER')=>`<article class="paper-content"><span class="eyebrow">${label}</span><h2>${title}</h2>${body}</article>`;
const mechanism=()=>`<svg class="mechanism" viewBox="0 0 580 235" role="img" aria-label="Three stages: thread restrains weight, candle burns thread, weight falls and pulls bell cord"><path stroke="#716442" stroke-width="2" fill="none" d="M20 25h140M77 25v55m0 0h46m-46 0v40M210 25h140m-83 0v55m0 0h18m10 0h18m-46 0v40M400 25h145m-90 0v140m0-100h50"/><path fill="#9d7b3c" d="M57 120h40v35H57zM247 120h40v35h-40zM435 165h40v35h-40z"/><path fill="#e8d9ad" stroke="#998657" d="M116 115h15v57h-15zM306 115h15v57h-15zM498 115h15v57h-15z"/><path fill="#a96935" d="M123 111q-14-14 0-26q14 14 0 26M313 91q-14-14 0-26q14 14 0 26M505 111q-14-14 0-26q14 14 0 26"/><text x="85" y="218" text-anchor="middle" font-size="12">1. Thread holds weight</text><text x="280" y="218" text-anchor="middle" font-size="12">2. Thread burns through</text><text x="475" y="218" text-anchor="middle" font-size="12">3. Weight pulls bell</text></svg><p class="note-small">Conceptual reconstruction, not a precise timer. The observed bell time was 10:15; burn duration cannot establish an exact interval.</p>`;
function contents(id){if(evidence[id]){if(id==='search'&&!canSearch(state))return paper('Grounds for a search',`<p>A private writing case cannot supply a convenient answer without grounds. First inspect the gardener’s statement and identify a discrepancy in the compensation accounts.</p><p class="feedback">${state.found.includes('gardener')?'✓ Witness account recorded.':'Missing: a witness connecting Clara to the ledger.'}<br>${state.rows.length?'✓ Financial discrepancy identified.':'Missing: compare a ledger entry with its signed receipt.'}</p><button data-paper="gardener">Read witness statement</button> <button data-paper="finance">Compare the accounts</button>`);const e=evidence[id];let extra='';if(id==='bell')extra=mechanism();if(id==='clock')extra='<div class="case-stamp" style="color:#786344;border-color:#786344">10:02</div><p class="note-small">An indication to corroborate, not a precise medical finding.</p>';if(id==='finance')extra=`<table class="ledger"><thead><tr><th>Family</th><th>Ledger</th><th>Receipt</th><th>Compare</th></tr></thead><tbody>${payments.map(([n,l,r],i)=>`<tr class="${state.rows.includes(i)?'selected':''}"><td>${n}<br><small>C.W. authorised</small></td><td>£${l}</td><td>£${r}</td><td><button data-row="${i}">${state.rows.includes(i)?'✓ Recorded':'Mark difference'}</button></td></tr>`).join('')}</tbody></table><p>Mrs. Bell’s concealed Hale letter confirms the family received £15. She hid their private circumstances, not a weapon or a key. The discrepancy is £25 for Hale, £20 for Bennett and £18 for Price: £63 altogether.</p><button data-paper="search">Review grounds to search Clara’s case →</button>`;if(id==='floor')extra='<svg class="floor-plan" viewBox="0 0 560 260" role="img" aria-label="Floor plan: billiard room and kitchen west of central hall; study and conservatory east; drawing room south"><g fill="none" stroke="#79694b" stroke-width="2"><path d="M20 20h520v220H20zM190 20v220M350 20v220M20 125h170M350 125h190M190 180h160"/></g><g font-size="13" text-anchor="middle"><text x="105" y="70">BILLIARD ROOM</text><text x="105" y="175">KITCHEN / HALL</text><text x="270" y="90">CENTRAL HALL</text><text x="270" y="215">DRAWING ROOM</text><text x="445" y="70">STUDY</text><text x="445" y="175">CONSERVATORY</text><text x="348" y="112" font-size="10">DOOR</text></g></svg>';return paper(e.title,`<p>${e.text}</p>${extra}<hr><p class="note-small">Recorded in your notebook. Evidence can be revisited in any order.</p><button data-paper="board">Take this to the evidence board →</button>`,e.label)}
if(id.startsWith('suspect-')){const s=suspects.find(s=>s.id===id.slice(8));return paper(s.name,`<div class="portrait" data-initials="${s.initials}" role="img" aria-label="Stylized silhouette portrait of ${s.name}"></div><p class="note-small">${s.role} / fictional portrait</p><blockquote>${s.statement}</blockquote><h3>Possible motive</h3><p>${s.motive}</p><h3>Verifiable movements</h3><p>${s.timeline}</p><h3>The secret behind the suspicion</h3><p>${s.secret}</p><button data-paper="suspects">← All four suspects</button>`)}
switch(id){case'intro':return paper('The Blackthorn Gazette',`<p class="news-headline">Industrialist found dead<br>behind locked door</p><p style="text-align:center"><em>“Household reports the study bell rang at a quarter past ten.”</em></p><hr><div class="news-columns"><p>November 1900. During last night’s storm, Sir Edmund Blackthorn was discovered dead in his private study. His personal key lay inside; the windows were fastened. The household insists that the bell was heard at 10:15.</p><p>Four people had reasons to fear or resent the industrialist. Their accounts agree on the sound. Whether they agree on its meaning remains to be determined.</p></div><button class="primary" data-start>Unfold the investigation →</button>`,'EVENING EDITION / NOVEMBER 1900');case'dossier':return paper('Instructions to the investigator',`<p>Sir Edmund Blackthorn, industrialist, was found in his locked study after the household heard its bell at 10:15 PM. The door was forced at approximately 10:18. The physician examined him at 10:24.</p><p>Your task is to identify the killer, explain the locked room and establish the evidence. Examine physical objects, compare statements and record supported deductions on the evidence board.</p><blockquote>The time someone heard a sound is not necessarily the time the event occurred.</blockquote><p>All four suspects’ accounts are available. The notebook collects facts automatically. The timeline lets you check their order; the evidence board accepts connections through two selectors, with no dragging required.</p><button data-paper="suspects">Read the household statements →</button>`);case'suspects':return paper('The household',`<div class="suspect-grid">${suspects.map(s=>`<section class="suspect-card"><div class="portrait" data-initials="${s.initials}" role="img" aria-label="Stylized silhouette of ${s.name}"></div><h3>${s.name}</h3><p class="note-small">${s.role}</p><button data-paper="suspect-${s.id}">Read statement →</button></section>`).join('')}</div>`);case'notebook':return paper('The investigator’s notebook',`<p class="note-small">Facts recorded as you examine evidence. Saved only in this browser.</p><ul class="notebook-list">${state.found.filter(k=>evidence[k]).map(k=>`<li><strong>${evidence[k].title}.</strong> ${evidence[k].text}</li>`).join('')||'<li>No evidence examined yet. Begin with the bronze clock or a witness statement.</li>'}</ul><p>${state.rows.length} financial discrepancies marked. ${state.deductions.length} deductions supported.</p><label for="personalnote">Your own observations</label><textarea id="personalnote" rows="4" style="width:100%;padding:.8rem;background:#efe5cd;border:1px solid #a59676;font:1rem/1.5 Georgia">${escape(state.notes)}</textarea><button data-save-note>Save note locally</button><p id="note-feedback" role="status"></p><hr><button data-hint>Need a nudge?</button><p id="hint" class="feedback" role="status">Hints progress from directions to explicit connections.</p>`);case'timeline':return paper('Thirteen minutes',`<p>Assign an event to each time. Consult the statements and exhibits; the clock’s stopped time is an inference corroborated by the wider record.</p><form id="timeline-form">${['10:02','10:04','10:08','10:15'].map((t,i)=>`<label class="timeline-row"><strong>${t}${i===1?' ≈':''}</strong><select name="${t}" aria-label="Event at ${t}"><option value="">Choose an event</option>${['Clock breaks during attack','Clara seen leaving with ledger','Clara joins drawing room','Household hears study bell'].map((v,j)=>`<option value="${j}" ${state.timeline[t]===String(j)?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<button class="primary">Check timeline</button></form><p id="timeline-feedback" class="feedback" role="status"></p>`);case'board':return paper('The evidence board',`<p>Connect two examined records. A connection must explain something specific; access or motive alone is not proof of murder.</p><form id="connect-form"><label>First record<select name="a" required><option value="">Choose evidence</option>${state.found.filter(k=>evidence[k]).map(k=>`<option value="${k}">${evidence[k].title}</option>`).join('')}</select></label><label>Related record<select name="b" required><option value="">Choose evidence</option>${state.found.filter(k=>evidence[k]).map(k=>`<option value="${k}">${evidence[k].title}</option>`).join('')}</select></label><button class="primary">Connect evidence</button></form><p id="connection-feedback" class="feedback" role="status">${canAccuse(state)?'All required deductions supported. The accusation is ready.':'Find the delayed bell, the duplicate-key explanation and the contradiction in Clara’s account.'}</p>${deductions.map(d=>`<div class="deduction ${state.deductions.includes(d.id)?'done':''}"><strong>${state.deductions.includes(d.id)?'✓':'○'} ${d.name}</strong><p>${state.deductions.includes(d.id)?d.text:'Not yet supported. Connect the relevant records above.'}</p></div>`).join('')}<button data-paper="accuse">Open accusation →</button>`);case'accuse':return canAccuse(state)?paper('The final accusation',`<p>State the culprit, weapon, motive and the corroborating records. An incorrect submission will let you revise your conclusion.</p><form id="accusation"><label>Who killed Sir Edmund?<select name="suspect"><option value="">Choose a suspect</option>${suspects.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></label><label>What caused his death?<select name="method"><option value="">Choose a method</option><option value="clock">Blunt-force attack with the bronze desk clock</option><option value="poison">Poison from the physician’s bag</option><option value="bell">Injury from the bell counterweight</option></select></label><label>Why?<select name="motive"><option value="">Choose a motive</option><option value="inheritance">Secure an inheritance</option><option value="fraud">Conceal diverted compensation payments before solicitor review</option><option value="revenge">Avenge a factory death</option></select></label><h3>Supporting evidence</h3>${['clock','gardener','key','bell','finance','search'].map(k=>`<label><input type="checkbox" name="proof" value="${k}"> ${evidence[k].title}</label>`).join('')}<button class="primary">Submit supported accusation →</button></form><p id="accusation-feedback" class="feedback" role="status"></p>`):paper('The seal remains intact',`<p>You have supported ${state.deductions.length} of three required deductions. Establish how the bell was delayed, how the door was locked and why Clara’s account fails.</p><button data-paper="board">Return to the evidence board →</button>`);case'report':return report();case'restart':return paper('Begin the investigation again?',`<p>This clears only Blackthorn Manor’s saved progress and personal notes from this browser. Case I remains unchanged.</p><button class="primary" data-restart>Clear Case II and restart</button> <button data-close>Keep investigating</button>`);default:return paper('Record unavailable','<p>Please return to the evidence desk.</p>')}}
function report(){return paper('What the bell concealed',`<p class="eyebrow">RECONSTRUCTION / ALL EVENTS FROM THE EVIDENCE</p><section class="reconstruction-step reveal-piece"><strong>10:02</strong><h3>The clock stops.</h3><p>Clara confronts Edmund about the compensation ledger. She strikes him with the bronze clock. The stopped hands suggest this time; the witness account and the physical record corroborate the sequence.</p></section><section class="reconstruction-step reveal-piece"><strong>About 10:04</strong><h3>A ledger leaves the study.</h3><p>After arranging the delayed pull, Clara takes the original ledger and leaves. She locks the conventional door from the corridor with the duplicate key. Samuel Pike sees her with the ledger.</p></section><section class="reconstruction-step reveal-piece"><strong>10:08</strong><h3>A perfectly real alibi.</h3><p>Clara joins the drawing room. The witnesses who see her there are telling the truth.</p></section><section class="reconstruction-step reveal-piece"><strong>10:15</strong><h3>The empty room calls.</h3><div class="split-scene"><div><strong>Drawing room</strong><p>Clara is visibly present with the household.</p></div><div><strong>Empty study</strong><p>The burned thread releases the weight. The mechanical bell-pull moves.</p></div></div>${mechanism()}</section><blockquote class="reveal-piece">Everyone remembered the bell. No one questioned who—or what—had rung it.</blockquote><div class="reveal-piece"><h3>Final report</h3><p><strong>Culprit:</strong> Clara Whitmore. <strong>Motive:</strong> conceal the diverted compensation payments before Edmund delivered the original ledger to his solicitor.</p><p><strong>Method:</strong> a fatal blow with the bronze clock, followed by a door locked from outside and a delayed bell to manufacture a misleading time marker.</p><p><strong>Proof:</strong> the clock and medical finding; Pike’s account contradicting Clara’s statement; the key register and recovered key; wax, thread, weight and abrasion; the altered accounts, signed receipts, original ledger and postponement note.</p><p>Julian’s threats, Ward’s scandal and Agnes’s hidden letter explained their evasiveness. Their verified movements and the disclosed records resolve the red herrings without requiring another culprit.</p><div class="case-stamp">CASE CLOSED</div><p class="note-small">Completed dossier saved in this browser. No report is transmitted.</p><div class="report-actions"><button data-return>Return to the archive →</button><button data-close>Revisit the evidence</button></div></div>`,'FINAL REPORT / SIR EDMUND BLACKTHORN')}
function openPaper(id){lastFocus=document.activeElement;if(evidence[id]&&(id!=='search'||canSearch(state))&&!state.found.includes(id)){state.found.push(id);save();renderDesk()}$('#evidence-content').innerHTML=contents(id);const dlg=$('#evidence-dialog');if(!dlg.open)dlg.showModal();dlg.scrollTop=0;$('.dialog-close').focus();const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('seen');io.unobserve(e.target)}}),{root:dlg,threshold:.08});dlg.querySelectorAll('.reveal-piece').forEach(e=>io.observe(e));if(id==='intro')$('.paper-content h2').classList.add('gazette')}
function closePaper(){$('#evidence-dialog').close();if(lastFocus?.isConnected)lastFocus.focus()}
$('.dialog-close').onclick=closePaper;$('#evidence-dialog').addEventListener('click',e=>{if(e.target===$('#evidence-dialog'))closePaper()});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.paper)openPaper(b.dataset.paper);if(b.hasAttribute('data-start')){state.intro=true;save();closePaper()}if(b.hasAttribute('data-row')){const n=Number(b.dataset.row);if(!state.rows.includes(n))state.rows.push(n);save();openPaper('finance')}if(b.hasAttribute('data-close'))closePaper();if(b.hasAttribute('data-return')){closePaper();openBook();location.hash='#/'}if(b.hasAttribute('data-restart')){state=initial();save();renderDesk();openPaper('intro')}if(b.hasAttribute('data-save-note')){state.notes=$('#personalnote').value;save();$('#note-feedback').textContent='Saved in this browser.'}if(b.hasAttribute('data-hint')){const hints=['Compare the stopped clock with the physical traces around the bell. What does a bell actually prove?','Read Samuel Pike’s statement. Compare the family receipts with the compensation ledger to justify a search.','Search Clara’s writing case after marking a discrepancy. Then connect the key register with the recovered contents.','Connect the bell-pull with the bronze clock; the key register with Clara’s writing case; the gardener’s statement with Clara’s writing case.','The evidence supports Clara, a blow with the bronze clock and concealment of compensation fraud. Select all six supporting records.'];$('#hint').textContent=hints[Math.min(state.hint++,4)];save()}});
document.addEventListener('submit',e=>{if(!['connect-form','timeline-form','accusation'].includes(e.target.id))return;e.preventDefault();const d=new FormData(e.target);if(e.target.id==='connect-form'){const a=d.get('a'),b=d.get('b');const match=deductions.find(x=>(x.a===a&&x.b===b)||(x.b===a&&x.a===b));if(match){if(!state.deductions.includes(match.id))state.deductions.push(match.id);save();renderDesk();openPaper('board');$('#connection-feedback').textContent='Supported: '+match.text}else $('#connection-feedback').textContent=a===b?'Choose two different records.':a==='key'||b==='key'?'This explains access to the study, but does not establish who used it. Look for corroboration from the writing case.':'These records do not yet establish one of the three deductions. Pair the physical mechanism with timing, or corroborate a statement with a recovered object.'}if(e.target.id==='timeline-form'){state.timeline=Object.fromEntries(d);save();const correct=['10:02','10:04','10:08','10:15'].every((t,i)=>state.timeline[t]===String(i));$('#timeline-feedback').textContent=correct?'The sequence fits the evidence. Clara’s drawing-room presence is compatible with an earlier attack.':'Recheck the clock, gardener and drawing-room statements. The bell is the last event, not the time of the attack.'}if(e.target.id==='accusation'){const a={suspect:d.get('suspect'),method:d.get('method'),motive:d.get('motive'),proof:d.getAll('proof')};if(canAccuse(state)&&correctAccusation(a)){state.solved=true;save();renderDesk();openPaper('report')}else $('#accusation-feedback').textContent=a.suspect!=='clara'?'This suspect is not supported by the corroborating records. Compare Clara’s denial with Pike’s statement and the recovered ledger.':a.method!=='clock'?'The examiner identifies fatal blunt-force trauma consistent with the bronze clock. The bell mechanism staged the timing.':a.motive!=='fraud'?'The solicitor letter and the discrepancies point to diverted compensation payments.':'Cite all six records: physical injury, witness contradiction, access, delayed bell, financial motive and recovered corroboration.'}});
status();route();
